import { useEffect, useMemo, useState } from 'react';
import {
  AlertTriangle, ArrowLeft, Bell, Building2, CheckCircle2, ChevronRight, ClipboardCheck, Clock3, FileSearch,
  FileText, Gauge, GitBranch, Inbox, Link2, Loader2, Plus, Search, ShieldAlert, ShieldCheck, Upload, Users, XCircle,
} from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { toast } from 'sonner';
import { useLocation, useSearchParams } from 'react-router-dom';
import { BulkVendorImportModal } from '../components/BulkVendorImportModal';
import { VendorOnboardingWizard } from '../components/VendorOnboardingWizard';
import { VendorSites } from '../components/VendorSites';
import { VendorRiskCases } from '../components/VendorRiskCases';
import { VendorRuleBuilder } from '../components/VendorRuleBuilder';
import { useAssets } from '../context/AssetContext';
import { useContracts } from '../context/ContractContext';
import { useVendors } from '../context/VendorContext';
import { ExternalVerification, RequirementResult, Vendor, VendorCheckStatus, VendorDocument, VendorOwnershipEntry, VendorPerformanceEvent, vendorDocumentTypes } from '../vendorTypes';

type View = 'workflow' | 'dashboard' | 'register' | 'followups' | 'expiries' | 'performance' | 'rules';
const fieldClass = 'w-full rounded-lg border border-gray-200 bg-white px-3 py-2 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100';
const checkStyles: Record<VendorCheckStatus, string> = {
  PENDING_EVIDENCE: 'bg-blue-50 text-blue-800',
  PASSED: 'bg-green-50 text-green-700', WARNING: 'bg-amber-50 text-amber-700', FAILED: 'bg-red-50 text-red-700',
  REVIEW_REQUIRED: 'bg-purple-50 text-purple-700', UNAVAILABLE: 'bg-gray-100 text-gray-600',
};
const onboardingStyles: Record<string, string> = {
  AWAITING_EVIDENCE: 'bg-blue-50 text-blue-800',
  APPROVED: 'bg-green-50 text-green-700', CONDITIONALLY_APPROVED: 'bg-amber-50 text-amber-700', REJECTED: 'bg-red-50 text-red-700',
  BLACKLISTED: 'bg-red-100 text-red-800', SUSPENDED: 'bg-red-50 text-red-700', VERIFYING: 'bg-blue-50 text-blue-700',
  IN_APPROVAL: 'bg-indigo-50 text-indigo-700', REVIEW_REQUIRED: 'bg-purple-50 text-purple-700', DOCUMENTS_PENDING: 'bg-gray-100 text-gray-700', DRAFT: 'bg-gray-100 text-gray-700',
};
const cleanLabel = (value: string) => value.replace(/_/g, ' ').toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase());
const displayDate = (value?: string) => value ? value.split('-').reverse().join('/') : '—';

function StatusBadge({ status }: { status: string }) {
  return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-bold ${checkStyles[status as VendorCheckStatus] || onboardingStyles[status] || 'bg-gray-100 text-gray-700'}`}>{cleanLabel(status)}</span>;
}

function DocumentEvidenceCard({ vendorId, document }: { vendorId: string; document: VendorDocument }) {
  const { updateDocumentFields } = useVendors();
  const [editing, setEditing] = useState(false);
  const [previewOpen, setPreviewOpen] = useState(false);
  const [fields, setFields] = useState(document.extractedFields.map(field => ({ key: field.key, value: field.value })));
  const [owners, setOwners] = useState<VendorOwnershipEntry[]>(document.ownershipEntries || []);
  useEffect(() => { setFields(document.extractedFields.map(field => ({ key: field.key, value: field.value }))); setOwners(document.ownershipEntries || []); }, [document]);
  const save = async () => {
    try { await updateDocumentFields(vendorId, document.id, fields, owners); toast.success('Extracted evidence updated'); setEditing(false); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to save extracted evidence'); }
  };
  const updateOwner = (index: number, patch: Partial<VendorOwnershipEntry>) => setOwners(current => current.map((item, itemIndex) => itemIndex === index ? { ...item, ...patch } : item));
  const previewUrl = `/api/vendors/${vendorId}/documents/${document.id}/preview`;
  return <div className="rounded-xl border border-gray-100 p-4">
    <div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><div className="truncate font-bold text-gray-900">{document.fileName}</div><div className="mt-1 text-xs text-gray-500">{cleanLabel(document.documentType)} · {(document.size / 1024 / 1024).toFixed(1)} MB{document.subjectName ? ` · ${document.subjectName}` : ''}</div></div><StatusBadge status={document.extractionStatus} /></div>
    <div className="mt-2 flex flex-wrap gap-4 text-xs font-bold"><button onClick={() => setPreviewOpen(true)} className="text-blue-700 underline">Preview document</button><a className="text-blue-700 underline" href={`/api/vendors/${vendorId}/documents/${document.id}/download`}>Download original evidence</a></div>
    {!!document.extractedFields.length && <div className="mt-4 grid gap-3 sm:grid-cols-2">{document.extractedFields.map((field, index) => <label key={`${field.key}-${index}`} className="text-xs text-gray-500"><span className="flex justify-between"><span>{field.label}</span><span>{Math.round(field.confidence * 100)}%</span></span>{editing ? <input className={`${fieldClass} mt-1`} value={fields[index]?.value || ''} onChange={event => setFields(current => current.map((item, itemIndex) => itemIndex === index ? { ...item, value: event.target.value } : item))} /> : <div className="mt-1 font-medium text-gray-900">{field.value || '—'} <span className="block text-[10px] font-normal text-gray-400">{field.sourceReference}</span></div>}</label>)}</div>}
    {((document.ownershipEntries?.length || 0) > 0 || ['SSM_PROFILE', 'SHAREHOLDER_REGISTER', 'BENEFICIAL_OWNERSHIP_DECLARATION'].includes(document.documentType)) && <div className="mt-4 rounded-lg border border-indigo-100 bg-indigo-50/40 p-3"><div className="text-xs font-bold text-indigo-950">Ownership evidence from this document</div><p className="mt-1 text-xs text-indigo-800">Directors and paid-up capital do not by themselves establish shareholding. Percentages are shown only when stated or calculable from evidenced shares and totals.</p>{owners.map((owner, index) => <div key={index} className="mt-3 grid gap-2 rounded-lg bg-white p-3 text-xs sm:grid-cols-4">{editing ? <><input className={fieldClass} value={owner.holderName} onChange={event => updateOwner(index, { holderName: event.target.value })} placeholder="Holder name" /><input className={fieldClass} type="number" min="0" max="100" step="0.01" value={owner.percentage ?? ''} onChange={event => updateOwner(index, { percentage: event.target.value === '' ? null : Number(event.target.value), percentageBasis: 'STATED' })} placeholder="Percentage" /><input className={fieldClass} value={owner.asOfDate} onChange={event => updateOwner(index, { asOfDate: event.target.value })} placeholder="YYYY-MM-DD" /><input className={fieldClass} value={owner.sourceReference} onChange={event => updateOwner(index, { sourceReference: event.target.value })} placeholder="Page / source" /><button className="text-left font-bold text-red-700" onClick={() => setOwners(current => current.filter((_, itemIndex) => itemIndex !== index))}>Remove owner</button></> : <><div className="font-bold text-gray-900">{owner.holderName}</div><div>{owner.percentage === null ? 'Share not established' : `${owner.percentage}% ${owner.percentageBasis === 'CALCULATED' ? '(calculated)' : '(stated)'}`}</div><div>{owner.ownershipType === 'BENEFICIAL' ? 'Beneficial owner' : 'Direct shareholder'}{owner.shareClass ? ` · ${owner.shareClass}` : ''}</div><div className="text-gray-500">{owner.asOfDate || 'Date not shown'} · {owner.sourceReference}</div></>}</div>)}{!owners.length && <div className="mt-2 text-xs text-amber-800">No ownership split was established from this document. Request a shareholder register or beneficial-ownership declaration.</div>}{editing && <button className="mt-3 text-xs font-bold text-blue-800" onClick={() => setOwners(current => [...current, { holderName: '', ownershipType: 'DIRECT', shareClass: '', sharesHeld: null, totalShares: null, percentage: null, percentageBasis: 'UNKNOWN', asOfDate: '', sourceReference: `Manual review of ${document.fileName}`, confidence: 1 }])}>+ Add evidenced holder</button>}</div>}
    <div className="mt-4 flex justify-end gap-2">{editing ? <><button onClick={() => { setEditing(false); setOwners(document.ownershipEntries || []); }} className="px-3 py-1.5 text-xs font-bold text-gray-500">Cancel</button><button onClick={save} className="rounded-lg bg-blue-800 px-3 py-1.5 text-xs font-bold text-white">Save corrections</button></> : <button onClick={() => setEditing(true)} className="rounded-lg bg-gray-50 px-3 py-1.5 text-xs font-bold text-blue-800">Review extracted fields</button>}</div>
    {previewOpen && <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-950/70 p-3 sm:p-6" role="dialog" aria-modal="true" aria-label={`Preview ${document.fileName}`}><div className="flex h-[90vh] w-full max-w-6xl flex-col overflow-hidden rounded-2xl bg-white"><div className="flex items-center justify-between border-b p-4"><div><div className="font-bold">{document.fileName}</div><div className="text-xs text-gray-500">{['application/pdf', 'image/png', 'image/jpeg'].includes(document.mimeType) ? 'Original document preview' : 'Extracted text preview; download for original formatting'}</div></div><button onClick={() => setPreviewOpen(false)} className="rounded-lg border px-3 py-2 text-sm font-bold">Close</button></div>{document.mimeType.startsWith('image/') ? <div className="flex-1 overflow-auto bg-gray-100 p-4"><img src={previewUrl} alt={document.fileName} className="mx-auto max-h-full max-w-full object-contain" /></div> : <iframe title={`Preview of ${document.fileName}`} src={previewUrl} className="w-full flex-1 bg-white" />}</div></div>}
  </div>;
}

function RequirementRow({ result, onUpload, onReview }: { result: RequirementResult; onUpload: (result: RequirementResult, files: File[]) => void; onReview: (result: RequirementResult) => void }) {
  const Icon = result.status === 'PASSED' ? CheckCircle2 : result.status === 'FAILED' ? XCircle : result.status === 'WARNING' ? AlertTriangle : Clock3;
  return <div className="flex items-start gap-3 rounded-xl border border-gray-100 p-4"><Icon className={`mt-0.5 h-5 w-5 shrink-0 ${result.status === 'PASSED' ? 'text-green-600' : result.status === 'FAILED' ? 'text-red-600' : 'text-amber-600'}`} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center justify-between gap-2"><div className="font-bold text-gray-900">{result.ruleName}</div><StatusBadge status={result.status} /></div><div className="mt-1 text-sm text-gray-500">{result.subjectName} · {result.scope === 'PERSON' ? 'Person-level' : 'Company-level'}{result.blocking ? ' · Blocking' : ''}</div><div className="mt-2 text-sm text-gray-700">{result.reason}</div>{result.expiresAt && <div className="mt-1 text-xs text-gray-500">Valid until {displayDate(result.expiresAt)}</div>}<div className="mt-3 flex flex-wrap gap-2">{result.status === 'PENDING_EVIDENCE' && result.requestedDocumentType && <label className="cursor-pointer rounded-lg bg-blue-800 px-3 py-2 text-xs font-bold text-white">Upload evidence<input type="file" multiple className="hidden" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx,.xlsx,.csv,.txt" onChange={event => { const files = Array.from(event.target.files || []).slice(0, 25); if (files.length) onUpload(result, files); event.target.value = ''; }} /></label>}{['REVIEW_REQUIRED', 'UNAVAILABLE', 'FAILED', 'WARNING'].includes(result.status) && <button onClick={() => onReview(result)} className="rounded-lg border border-blue-200 px-3 py-2 text-xs font-bold text-blue-800">Review evidence and finding</button>}</div></div></div>;
}

function VendorChecklistCard({ vendor }: { vendor: Vendor }) {
  const pending = vendor.requirementResults.filter(result => result.status === 'PENDING_EVIDENCE');
  const requestable = pending.filter(result => !!result.requestedDocumentType);
  const lines = requestable.map(result => result.subjectName === 'Personnel roster'
    ? `Named personnel roster for ${result.ruleName}`
    : `${result.requestedDocumentType!.replaceAll('_', ' ')}${result.scope === 'PERSON' ? ` — ${result.subjectName}` : ''}`);
  const requestText = `Dear ${vendor.contactName || 'Vendor'},\n\nTo continue onboarding ${vendor.legalName}, please provide the following outstanding items:\n\n${lines.map(line => `• ${line}`).join('\n')}\n\nPlease ensure documents are current and legible. Thank you.`;
  return <section className="rounded-xl border border-blue-100 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="font-bold text-blue-950">Onboarding evidence checklist</h2><p className="mt-1 text-xs text-gray-500">{vendor.requirementResults.length} applicable checks · {pending.length} awaiting evidence · rule pack v{vendor.ruleVersion}</p></div>{requestable.length > 0 && <div className="flex gap-2"><button onClick={() => navigator.clipboard.writeText(requestText).then(() => toast.success('Document request copied')).catch(() => toast.error('Could not copy the request'))} className="rounded-lg border border-blue-200 px-3 py-2 text-xs font-bold text-blue-800">Copy request</button>{vendor.email && <a href={`mailto:${encodeURIComponent(vendor.email)}?subject=${encodeURIComponent(`Documents required for ${vendor.legalName} onboarding`)}&body=${encodeURIComponent(requestText)}`} className="rounded-lg bg-blue-800 px-3 py-2 text-xs font-bold text-white">Draft email</a>}</div>}</div><div className="mt-4 grid gap-2 sm:grid-cols-2">{vendor.requirementResults.map(result => <div key={result.id} className="flex items-start justify-between gap-3 rounded-lg border border-gray-100 p-3"><div className="min-w-0"><div className="text-sm font-bold">{result.ruleName}{result.scope === 'PERSON' ? ` · ${result.subjectName}` : ''}</div><div className="mt-1 text-xs text-gray-500">{result.requestedDocumentType?.replaceAll('_', ' ') || (result.ruleId === 'agreement' ? 'Link a contract' : 'System or manual check')}</div></div><StatusBadge status={result.status} /></div>)}</div>{requestable.length > 0 && <p className="mt-3 text-xs text-blue-700">Draft email opens your mail app; this system does not send it automatically. Upload received evidence below to resume background checks.</p>}</section>;
}

function RecommendationRationale({ vendor }: { vendor: Vendor }) {
  const target = vendor.recommendation === 'RECOMMEND_REJECT' ? ['FAILED'] : vendor.recommendation === 'AWAITING_EVIDENCE' ? ['PENDING_EVIDENCE'] : vendor.recommendation === 'NEEDS_REVIEW' ? ['REVIEW_REQUIRED', 'UNAVAILABLE'] : vendor.recommendation === 'RECOMMEND_CONDITIONAL' ? ['WARNING'] : ['PASSED'];
  const reasons = vendor.requirementResults.filter(result => target.includes(result.status) && (result.blocking || vendor.recommendation === 'RECOMMEND_APPROVE')).slice(0, 5);
  return <div className="mt-4 rounded-lg border border-gray-100 bg-gray-50 p-4"><div className="text-xs font-bold uppercase tracking-wide text-gray-600">Why this outcome?</div><div className="mt-2 space-y-3">{reasons.map(result => <div key={result.id} className="text-xs"><div className="font-bold text-gray-900">{result.ruleName}{result.scope === 'PERSON' ? ` · ${result.subjectName}` : ''}</div><div className="mt-0.5 text-gray-600">{result.reason}</div><div className="mt-1 flex flex-wrap gap-2">{result.evidenceIds.map(id => <a key={id} className="font-bold text-blue-700 underline" href={`/api/vendors/${vendor.id}/documents/${id}/preview`} target="_blank" rel="noreferrer">View evidence</a>)}{result.verificationIds.flatMap(id => vendor.verifications.filter(check => check.id === id).flatMap(check => check.citations.map(citation => <a key={`${id}:${citation.url}`} className="font-bold text-blue-700 underline" href={citation.url} target="_blank" rel="noreferrer">{citation.title}</a>)))}</div></div>)}{!reasons.length && <div className="text-xs text-gray-500">No material blocker is recorded. Review each applicable check and its evidence before a human decision.</div>}</div></div>;
}

function VendorOwnershipSummary({ vendor }: { vendor: Vendor }) {
  const sources = vendor.documents.filter(document => (document.ownershipEntries || []).length > 0);
  const hasOwnershipDocument = vendor.documents.some(document => ['SSM_PROFILE', 'SHAREHOLDER_REGISTER', 'BENEFICIAL_OWNERSHIP_DECLARATION'].includes(document.documentType));
  return <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><h2 className="font-bold text-blue-950">Ownership and shareholding</h2><p className="mt-1 text-xs text-gray-500">Evidence-backed holdings only. Different dated sources remain separate; directors are not assumed to be shareholders.</p>{sources.map(document => <div key={document.id} className="mt-4 rounded-lg border p-3"><div className="flex flex-wrap justify-between gap-2 text-sm font-bold"><span>{document.fileName}</span><a href={`/api/vendors/${vendor.id}/documents/${document.id}/preview`} target="_blank" rel="noreferrer" className="text-xs text-blue-700 underline">View source</a></div><div className="mt-3 overflow-x-auto"><table className="w-full min-w-[500px] text-left text-xs"><thead className="border-b text-gray-500"><tr><th className="py-2">Holder</th><th>Interest</th><th>Type</th><th>As of / source</th></tr></thead><tbody>{document.ownershipEntries!.map((entry, index) => <tr key={index} className="border-b last:border-0"><td className="py-2 font-semibold">{entry.holderName}</td><td>{entry.percentage === null ? 'Unknown' : `${entry.percentage}%`}{entry.percentageBasis === 'CALCULATED' ? ' (calculated)' : ''}</td><td>{entry.ownershipType === 'BENEFICIAL' ? 'Beneficial' : 'Direct'}{entry.shareClass ? ` · ${entry.shareClass}` : ''}</td><td>{entry.asOfDate || 'Undated'} · {entry.sourceReference}</td></tr>)}</tbody></table></div></div>)}{!sources.length && <div className="mt-4 rounded-lg border border-amber-100 bg-amber-50 p-3 text-sm text-amber-900">{hasOwnershipDocument ? 'Uploaded corporate documents did not establish exact holders and percentages. Review the originals and request a current shareholder register or ownership declaration.' : 'No shareholding evidence has been uploaded. Request a current shareholder register or ownership declaration to identify who owns how much.'}</div>}</section>;
}

function ExternalVerificationCard({ vendorId, check }: { vendorId: string; check: ExternalVerification }) {
  const { recordManualVerification } = useVendors();
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [form, setForm] = useState({ status: 'PASSED' as 'PASSED' | 'WARNING' | 'FAILED', officialName: check.officialName || '', registrationNumber: check.registrationNumber || '', scope: check.scope || '', validUntil: check.validUntil || '', evidenceUrl: '', notes: '' });
  const submit = async () => {
    setSaving(true);
    try { await recordManualVerification(vendorId, check.id, form); toast.success('Official manual result recorded'); setOpen(false); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to record the manual result'); }
    finally { setSaving(false); }
  };
  return <div className="rounded-xl border border-gray-100 p-4">
    <div className="flex flex-wrap justify-between gap-2"><div className="font-bold">{cleanLabel(check.connector)}</div><StatusBadge status={check.status} /></div>
    <p className="mt-2 text-sm leading-6 text-gray-600">{check.summary}</p>
    <div className="mt-2 text-xs text-gray-400">{check.authority} · Checked {new Date(check.checkedAt).toLocaleString()}</div>
    <div className="mt-2 flex flex-wrap gap-2">{check.citations.map(citation => <a key={citation.url} href={citation.url} target="_blank" rel="noreferrer" className="rounded bg-blue-50 px-2 py-1 text-xs font-bold text-blue-700">{citation.title}</a>)}</div>
    {check.limitation && <div className="mt-2 text-xs font-medium text-amber-700">Limitation: {check.limitation}</div>}
    {['REVIEW_REQUIRED', 'UNAVAILABLE'].includes(check.status) && <button onClick={() => setOpen(value => !value)} className="mt-3 rounded-lg bg-purple-50 px-3 py-2 text-xs font-bold text-purple-700">Record official manual result</button>}
    {open && <div className="mt-4 grid gap-2 border-t pt-4 sm:grid-cols-2">
      <select className={fieldClass} value={form.status} onChange={event => setForm({...form, status: event.target.value as typeof form.status})}><option value="PASSED">Passed</option><option value="WARNING">Warning</option><option value="FAILED">Failed</option></select>
      <input className={fieldClass} value={form.officialName} onChange={event => setForm({...form, officialName: event.target.value})} placeholder="Official registered name" />
      <input className={fieldClass} value={form.registrationNumber} onChange={event => setForm({...form, registrationNumber: event.target.value})} placeholder="Registration / certificate number" />
      <input className={fieldClass} value={form.scope} onChange={event => setForm({...form, scope: event.target.value})} placeholder="Grade / category / competency scope" />
      <label className="text-xs text-gray-600">Valid until<input type="date" className={`${fieldClass} mt-1`} value={form.validUntil} onChange={event => setForm({...form, validUntil: event.target.value})} /></label>
      <input type="url" className={fieldClass} value={form.evidenceUrl} onChange={event => setForm({...form, evidenceUrl: event.target.value})} placeholder="Evidence URL (optional)" />
      <textarea className={`${fieldClass} sm:col-span-2`} rows={2} value={form.notes} onChange={event => setForm({...form, notes: event.target.value})} placeholder="Reviewer findings and evidence notes *" />
      <div className="flex justify-end gap-2 sm:col-span-2"><button onClick={() => setOpen(false)} className="px-3 py-2 text-xs font-bold text-gray-500">Cancel</button><button onClick={submit} disabled={saving || !form.notes.trim()} className="rounded-lg bg-blue-800 px-3 py-2 text-xs font-bold text-white disabled:opacity-50">{saving ? 'Saving…' : 'Save result'}</button></div>
    </div>}
  </div>;
}

function PerformanceForm({ vendor }: { vendor: Vendor }) {
  const { recordPerformance, recordPerformanceEvent, updatePerformanceEvent } = useVendors();
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [comments, setComments] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);
  const [editingId, setEditingId] = useState('');
  const blankEvent = (): Partial<VendorPerformanceEvent> => ({ metric: 'quality', kind: 'KPI', title: '', occurredOn: new Date().toISOString().slice(0, 10), siteName: '', observedValue: undefined, targetValue: undefined, unit: '', notes: '', documentIds: [] });
  const [eventDraft, setEventDraft] = useState<Partial<VendorPerformanceEvent>>(blankEvent);
  const keys = ['quality', 'delivery', 'cost', 'service', 'safety', 'compliance'] as const;
  const [scores, setScores] = useState<Record<typeof keys[number], number>>({ quality: 80, delivery: 80, cost: 80, service: 80, safety: 80, compliance: 80 });
  const weights: Record<typeof keys[number], number> = { quality: 20, delivery: 20, cost: 15, service: 15, safety: 15, compliance: 15 };
  const saveEvent = async () => {
    setSaving(true);
    try {
      if (editingId) await updatePerformanceEvent(vendor.id, editingId, eventDraft);
      else await recordPerformanceEvent(vendor.id, eventDraft);
      toast.success(editingId ? 'Performance evidence updated.' : 'Performance evidence recorded.');
      setEditingId(''); setEventDraft(blankEvent());
    } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to record performance evidence.'); }
    finally { setSaving(false); }
  };
  const submit = async () => {
    setSaving(true);
    try { await recordPerformance(vendor.id, { period: String(new Date().getFullYear()), scores, weights, comments, eventIds: selectedIds }); toast.success('Evidence-linked annual review recorded.'); setOpen(false); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to save performance review'); }
    finally { setSaving(false); }
  };
  const latest = vendor.performanceAssessments[0];
  return <div className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm">
    <div className="flex flex-wrap items-center justify-between gap-2"><div className="flex items-center gap-2 font-bold text-blue-950"><Gauge className="h-5 w-5" />Performance evidence and annual review</div><button onClick={() => setOpen(value => !value)} className="rounded-lg bg-blue-50 px-3 py-2 text-xs font-bold text-blue-800">Record annual review</button></div>
    {latest ? <div className="mt-4 flex items-center justify-between rounded-xl bg-gray-50 p-4"><div><div className="text-sm font-bold">Latest score</div><div className="mt-1 text-xs text-gray-500">Period {latest.period} · {latest.eventIds?.length || 0} frozen evidence item(s) · Next {displayDate(latest.nextReviewDate)}</div></div><div className="text-3xl font-bold text-blue-800">{latest.weightedScore}</div></div> : <div className="mt-4 rounded-xl border border-dashed p-4 text-sm text-gray-500">No annual review has been recorded. Log measurable events first.</div>}
    <div className="mt-4 space-y-2">{(vendor.performanceEvents || []).map(item => <div key={item.id} className="rounded-lg border p-3 text-sm"><div className="flex flex-wrap justify-between gap-2"><div className="font-bold">{item.title} · {cleanLabel(item.metric)}</div><div className="text-xs text-slate-500">{item.kind} · {item.occurredOn} · {item.status}</div></div><div className="mt-1 text-xs text-slate-600">{item.observedValue !== undefined ? `${item.observedValue}${item.unit ? ` ${item.unit}` : ''} observed${item.targetValue !== undefined ? ` / ${item.targetValue} target` : ''} · ` : ''}{item.siteName ? `${item.siteName} · ` : ''}{item.notes || 'Document evidence attached'}</div><div className="mt-2 flex flex-wrap gap-2">{item.documentIds.map(id => <span key={id} className="rounded bg-indigo-50 px-2 py-1 text-xs text-indigo-700">{vendor.documents.find(document => document.id === id)?.fileName || 'Evidence file'}</span>)}<button onClick={() => { setEditingId(item.id); setEventDraft({ ...item }); }} className="text-xs font-bold text-blue-700">Edit event</button>{item.status === 'OPEN' && <button onClick={() => { const resolution = window.prompt('Resolution and corrective-action evidence'); if (resolution?.trim()) void updatePerformanceEvent(vendor.id, item.id, { resolution }).then(() => toast.success('Event resolved.')).catch(error => toast.error(error.message)); }} className="text-xs font-bold text-emerald-700">Resolve</button>}</div></div>)}{!vendor.performanceEvents?.length && <div className="text-sm text-slate-500">No KPI, incident or corrective-action evidence yet.</div>}</div>
    <div className="mt-4 grid gap-3 border-t pt-4 sm:grid-cols-2"><label className="text-xs font-bold">Evidence type<select className={fieldClass} value={eventDraft.kind} onChange={event => setEventDraft({ ...eventDraft, kind: event.target.value as VendorPerformanceEvent['kind'] })}><option value="KPI">KPI</option><option value="INCIDENT">Incident</option><option value="COMPLAINT">Complaint</option><option value="CORRECTIVE_ACTION">Corrective action</option></select></label><label className="text-xs font-bold">Metric<select className={fieldClass} value={eventDraft.metric} onChange={event => setEventDraft({ ...eventDraft, metric: event.target.value as VendorPerformanceEvent['metric'] })}>{keys.map(key => <option key={key} value={key}>{cleanLabel(key)}</option>)}</select></label><label className="text-xs font-bold sm:col-span-2">Title<input className={fieldClass} value={eventDraft.title || ''} onChange={event => setEventDraft({ ...eventDraft, title: event.target.value })} placeholder="e.g. Delivery on-time rate, safety incident" /></label><label className="text-xs font-bold">Date<input type="date" className={fieldClass} value={eventDraft.occurredOn || ''} onChange={event => setEventDraft({ ...eventDraft, occurredOn: event.target.value })} /></label><label className="text-xs font-bold">Site / project<input className={fieldClass} value={eventDraft.siteName || ''} onChange={event => setEventDraft({ ...eventDraft, siteName: event.target.value })} /></label><label className="text-xs font-bold">Observed value<input type="number" className={fieldClass} value={eventDraft.observedValue ?? ''} onChange={event => setEventDraft({ ...eventDraft, observedValue: event.target.value === '' ? undefined : Number(event.target.value) })} /></label><label className="text-xs font-bold">Target value<input type="number" className={fieldClass} value={eventDraft.targetValue ?? ''} onChange={event => setEventDraft({ ...eventDraft, targetValue: event.target.value === '' ? undefined : Number(event.target.value) })} /></label><label className="text-xs font-bold">Unit<input className={fieldClass} value={eventDraft.unit || ''} onChange={event => setEventDraft({ ...eventDraft, unit: event.target.value })} placeholder="%, days, incidents" /></label><label className="text-xs font-bold sm:col-span-2">Source or observation<textarea className={fieldClass} rows={2} value={eventDraft.notes || ''} onChange={event => setEventDraft({ ...eventDraft, notes: event.target.value })} placeholder="Who measured this, from which report, and what happened?" /></label><div className="sm:col-span-2"><div className="text-xs font-bold">Supporting uploaded documents</div><div className="mt-2 flex flex-wrap gap-3">{vendor.documents.map(document => <label key={document.id} className="flex items-center gap-1 text-xs"><input type="checkbox" checked={eventDraft.documentIds?.includes(document.id) || false} onChange={event => setEventDraft({ ...eventDraft, documentIds: event.target.checked ? [...(eventDraft.documentIds || []), document.id] : (eventDraft.documentIds || []).filter(id => id !== document.id) })} />{document.fileName}</label>)}{!vendor.documents.length && <span className="text-xs text-slate-500">Upload supporting files in Documents, or record a named manual observation.</span>}</div></div><div className="flex gap-2 sm:col-span-2"><button disabled={saving || !eventDraft.title?.trim()} onClick={saveEvent} className="rounded-lg bg-blue-800 px-4 py-2 text-xs font-bold text-white disabled:opacity-40">{editingId ? 'Save event changes' : 'Record evidence event'}</button>{editingId && <button onClick={() => { setEditingId(''); setEventDraft(blankEvent()); }} className="rounded-lg border px-4 py-2 text-xs font-bold">Cancel edit</button>}</div></div>
    {open && <div className="mt-4 space-y-3 border-t pt-4"><p className="text-xs text-slate-600">Select the measured events underpinning this review. Their details are frozen in the assessment; later corrections remain auditable.</p><div className="space-y-2">{(vendor.performanceEvents || []).map(item => <label key={item.id} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={selectedIds.includes(item.id)} onChange={event => setSelectedIds(current => event.target.checked ? [...current, item.id] : current.filter(id => id !== item.id))} />{item.title} · {item.occurredOn}</label>)}</div><div className="grid gap-3 sm:grid-cols-2">{keys.map(key => <label key={key} className="text-xs font-medium text-gray-600">{cleanLabel(key)} · weight {weights[key]}%<input type="number" min="0" max="100" className={`${fieldClass} mt-1`} value={scores[key]} onChange={event => setScores(current => ({ ...current, [key]: Number(event.target.value) }))} /></label>)}</div><textarea className={fieldClass} rows={2} value={comments} onChange={event => setComments(event.target.value)} placeholder="Explain how evidence supports the weighted scores" /><div className="flex justify-end"><button onClick={submit} disabled={saving || !selectedIds.length} className="rounded-lg bg-blue-800 px-4 py-2 text-sm font-bold text-white disabled:opacity-50">{saving ? 'Saving…' : 'Save evidence-linked review'}</button></div></div>}
  </div>;
}

type VendorDetailTab = 'overview' | 'checklist' | 'documents' | 'people' | 'performance' | 'decisions';

function VendorDetail({ vendor, onBack, initialTab = 'overview' }: { vendor: Vendor; onBack: () => void; initialTab?: VendorDetailTab }) {
  const { configuration, jobs, uploadDocuments, runChecks, completeFollowUp, submitApproval, setLifecycleStatus, linkEntity, updateVendor, selectAgreement } = useVendors();
  const { assets } = useAssets();
  const { contracts } = useContracts();
  const [fileList, setFileList] = useState<File[]>([]);
  const [documentType, setDocumentType] = useState('OTHER');
  const [subjectId, setSubjectId] = useState('');
  const [approvalNotes, setApprovalNotes] = useState('');
  const [lifecycleReason, setLifecycleReason] = useState('');
  const [assetId, setAssetId] = useState('');
  const [relationship, setRelationship] = useState('MAINTENANCE_PROVIDER');
  const [operatorId, setOperatorId] = useState('');
  const [busy, setBusy] = useState(false);
  const [detailTab, setDetailTab] = useState<VendorDetailTab>(initialTab);
  const [editingProfile, setEditingProfile] = useState(false);
  const [profile, setProfile] = useState({ legalName: vendor.legalName, registrationNumber: vendor.registrationNumber, categoryId: vendor.categoryId, contactName: vendor.contactName, email: vendor.email, phone: vendor.phone, address: vendor.address, services: vendor.services.join(', '), taxProfile: vendor.taxProfile || { tin: '', msic: '', businessActivity: '', sstNumber: '', tourismTaxNumber: '' } });
  useEffect(() => setProfile({ legalName: vendor.legalName, registrationNumber: vendor.registrationNumber, categoryId: vendor.categoryId, contactName: vendor.contactName, email: vendor.email, phone: vendor.phone, address: vendor.address, services: vendor.services.join(', '), taxProfile: vendor.taxProfile || { tin: '', msic: '', businessActivity: '', sstNumber: '', tourismTaxNumber: '' } }), [vendor.id]);
  const saveProfile = async () => { setBusy(true); try { await updateVendor(vendor.id, { ...profile, services: profile.services.split(',').map(item => item.trim()).filter(Boolean) }); setEditingProfile(false); toast.success('Vendor profile updated; rerun verification'); } catch (error) { toast.error(error instanceof Error ? error.message : 'Could not update vendor'); } finally { setBusy(false); } };
  const activeJob = jobs.find(job => job.vendorId === vendor.id && !['COMPLETED', 'PARTIAL', 'FAILED'].includes(job.stage));
  const nextStage = configuration?.approvalStages[vendor.currentApprovalStage];
  const linkedContracts = contracts.filter(contract => !!vendor.entityId && [contract.primaryEntityId, ...contract.coveredEntityIds].includes(vendor.entityId)
    && (contract.vendorId === vendor.id || (!!contract.counterpartyRegistrationNumber && contract.counterpartyRegistrationNumber.toLowerCase().replace(/[^a-z0-9]/g, '') === vendor.registrationNumber.toLowerCase().replace(/[^a-z0-9]/g, ''))));
  const agreementResult = vendor.requirementResults.find(result => result.ruleId === 'agreement');
  const chooseAgreement = async (contractId: string) => {
    setBusy(true);
    try { await selectAgreement(vendor.id, contractId); toast.success('Governing agreement updated'); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to select agreement'); }
    finally { setBusy(false); }
  };

  const upload = async () => {
    if (!fileList.length) return;
    setBusy(true);
    try { await uploadDocuments(vendor.id, fileList.map(file => ({ file, declaredType: documentType, subjectId: subjectId || undefined }))); toast.success('Background document verification started'); setFileList([]); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Upload failed'); }
    finally { setBusy(false); }
  };
  const verify = async () => {
    setBusy(true); try { await runChecks(vendor.id); toast.success('Compliance verification queued'); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to start checks'); } finally { setBusy(false); }
  };
  const uploadRequirementEvidence = async (result: RequirementResult, files: File[]) => {
    setBusy(true);
    try { const accepted = files.slice(0, 25); await uploadDocuments(vendor.id, accepted.map(file => ({ file, declaredType: result.requestedDocumentType, subjectId: result.subjectId }))); toast.success(`${accepted.length} file(s) mapped to ${result.ruleName} and queued for verification`); setDetailTab('documents'); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Upload failed'); }
    finally { setBusy(false); }
  };
  const reviewRequirement = (_result: RequirementResult) => setDetailTab('documents');
  const decide = async (decision: 'APPROVED' | 'CONDITIONAL' | 'REJECTED') => {
    setBusy(true); try { await submitApproval(vendor.id, decision, approvalNotes); toast.success('Approval decision recorded'); setApprovalNotes(''); } catch (error) { toast.error(error instanceof Error ? error.message : 'Decision could not be recorded'); } finally { setBusy(false); }
  };
  const changeLifecycle = async (status: 'SUSPENDED' | 'BLACKLISTED' | 'APPROVED') => {
    if (!lifecycleReason.trim()) return toast.error('Enter a reason for this lifecycle action');
    setBusy(true);
    try { await setLifecycleStatus(vendor.id, status, lifecycleReason); toast.success(status === 'APPROVED' ? 'Vendor reinstated' : `Vendor ${status.toLowerCase()}`); setLifecycleReason(''); }
    catch (error) { toast.error(error instanceof Error ? error.message : 'Lifecycle action could not be recorded'); }
    finally { setBusy(false); }
  };
  const addLink = async () => {
    const asset = assets.find(item => item.id === assetId); if (!asset) return;
    setBusy(true); try { await linkEntity(vendor.id, { entityType: 'ASSET', entityId: asset.id, entityName: `${asset.name} (${asset.registrationNumber})`, relationship, personnelId: relationship === 'OPERATOR' ? operatorId : undefined }); toast.success('Asset linked to vendor'); setAssetId(''); setOperatorId(''); } catch (error) { toast.error(error instanceof Error ? error.message : 'Unable to link asset'); } finally { setBusy(false); }
  };

  return <div className="space-y-6">
    <div className="flex flex-wrap items-start justify-between gap-4"><div className="flex items-start gap-3"><button onClick={onBack} className="mt-1 rounded-full p-2 text-gray-400 hover:bg-blue-50 hover:text-blue-800"><ArrowLeft className="h-5 w-5" /></button><div><div className="flex flex-wrap items-center gap-3"><h1 className="text-2xl font-bold text-blue-950">{vendor.legalName}</h1><StatusBadge status={vendor.onboardingStatus} /></div><div className="mt-1 text-sm text-gray-500">{vendor.registrationNumber} · {vendor.categoryName} · Rule pack v{vendor.ruleVersion}</div></div></div><button onClick={verify} disabled={busy || !!activeJob} className="inline-flex items-center gap-2 rounded-lg bg-blue-800 px-4 py-2.5 text-sm font-bold text-white disabled:opacity-50"><ShieldCheck className="h-4 w-4" />Run compliance checks</button></div>
    {activeJob && <div className="rounded-xl border border-blue-100 bg-blue-50 p-4"><div className="flex justify-between text-sm"><span className="font-bold text-blue-900">{cleanLabel(activeJob.stage)}</span><span className="text-blue-700">{activeJob.progress}%</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-blue-100"><div className="h-full bg-blue-700 transition-all" style={{ width: `${activeJob.progress}%` }} /></div><div className="mt-2 text-xs text-blue-700">{activeJob.message}</div></div>}

    <nav className="flex gap-1 overflow-x-auto rounded-xl border border-gray-100 bg-gray-50 p-1" aria-label="Vendor workspace sections">{([['overview', 'Overview'], ['checklist', 'Checklist'], ['documents', 'Documents & review'], ['people', 'Personnel & sites'], ['performance', 'Performance'], ['decisions', 'Approvals & audit']] as const).map(([key, label]) => <button key={key} onClick={() => setDetailTab(key)} className={`shrink-0 rounded-lg px-4 py-2.5 text-sm font-bold ${detailTab === key ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500 hover:text-blue-800'}`}>{label}</button>)}</nav>

    <div className={`grid gap-6 ${['overview', 'checklist', 'people'].includes(detailTab) ? 'xl:grid-cols-[1.45fr_0.75fr]' : ''}`}>
      <div className="space-y-6">
        {detailTab === 'overview' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3"><div><div className="text-xs font-bold uppercase tracking-widest text-gray-400">AI-assisted outcome</div><div className="mt-2 text-xl font-bold text-blue-950">{vendor.recommendation === 'AWAITING_EVIDENCE' ? 'Awaiting vendor evidence' : cleanLabel(vendor.recommendation)}</div></div><StatusBadge status={vendor.recommendation === 'RECOMMEND_APPROVE' ? 'PASSED' : vendor.recommendation === 'RECOMMEND_REJECT' ? 'FAILED' : vendor.recommendation === 'AWAITING_EVIDENCE' ? 'PENDING_EVIDENCE' : 'REVIEW_REQUIRED'} /></div><p className="mt-3 text-sm leading-6 text-gray-600">{vendor.recommendationSummary}</p><RecommendationRationale vendor={vendor} /><div className="mt-4 rounded-lg bg-amber-50 px-4 py-3 text-xs text-amber-800">AI findings support the review. Admin User remains responsible for the final decision.</div></section>}

        {detailTab === 'checklist' && <VendorChecklistCard vendor={vendor} />}
        {detailTab === 'overview' && <VendorOwnershipSummary vendor={vendor} />}

        {detailTab === 'checklist' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><ClipboardCheck className="h-5 w-5" />Applicable requirements</div><p className="mt-1 text-xs text-gray-500">Upload against a pending item here. Unstructured uploads in Documents are classified and attached to the matching item automatically.</p><div className="mt-4 space-y-3">{vendor.requirementResults.map(result => <RequirementRow key={result.id} result={result} onUpload={uploadRequirementEvidence} onReview={reviewRequirement} />)}{!vendor.requirementResults.length && <div className="rounded-xl border border-dashed p-6 text-center text-sm text-gray-500">Confirm the vendor category and activities to calculate its checklist.</div>}</div></section>}

        {detailTab === 'documents' && <section id="vendor-documents" className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><FileSearch className="h-5 w-5" />Documents and extracted evidence</div><p className="mt-1 text-xs text-gray-500">Upload unstructured evidence and let AI classify and map it to the correct checklist rule. Select a type only when you already know it.</p><div className="mt-4 grid gap-3 rounded-xl bg-gray-50 p-4 sm:grid-cols-3"><select className={fieldClass} value={documentType} onChange={event => setDocumentType(event.target.value)}><option value="OTHER">Auto-classify against checklist (recommended)</option>{vendorDocumentTypes.filter(type => type !== 'OTHER').map(type => <option key={type} value={type}>{cleanLabel(type)}</option>)}</select><select className={fieldClass} value={subjectId} onChange={event => setSubjectId(event.target.value)}><option value="">Company or let AI identify person</option>{vendor.personnel.map(person => <option key={person.id} value={person.id}>{person.name}</option>)}</select><label className="flex cursor-pointer items-center justify-center gap-2 rounded-lg border border-dashed border-gray-300 bg-white px-3 py-2 text-sm font-bold text-blue-800"><Upload className="h-4 w-4" />{fileList.length ? `${fileList.length} selected` : 'Choose up to 25 files'}<input type="file" multiple className="hidden" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx,.xlsx,.csv,.txt" onChange={event => setFileList(Array.from(event.target.files || []).slice(0, 25))} /></label><button onClick={upload} disabled={!fileList.length || busy} className="rounded-lg bg-blue-800 px-4 py-2 text-sm font-bold text-white disabled:opacity-50 sm:col-start-3">Upload, classify and verify</button></div><div className="mt-4 space-y-3">{vendor.documents.map(document => <DocumentEvidenceCard key={document.id} vendorId={vendor.id} document={document} />)}{!vendor.documents.length && <div className="rounded-xl border border-dashed p-8 text-center text-sm text-gray-500">No supporting documents uploaded.</div>}</div></section>}

        {detailTab === 'documents' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><ShieldAlert className="h-5 w-5" />External verification and inline review</div><p className="mt-1 text-xs text-gray-500">Review uncertain, unavailable or conflicting checks here without leaving the vendor case.</p><div className="mt-4 space-y-3">{vendor.verifications.map(check => <ExternalVerificationCard key={check.id} vendorId={vendor.id} check={check} />)}{!vendor.verifications.length && <div className="rounded-xl border border-dashed p-6 text-center text-sm text-gray-500">External checks have not run.</div>}</div></section>}
        {detailTab === 'documents' && <VendorRiskCases vendor={vendor} />}
        {detailTab === 'people' && <VendorSites vendor={vendor} />}
      </div>

      <aside className="space-y-6">
        {detailTab === 'overview' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><FileText className="h-5 w-5" />Governing agreement</div><p className="mt-2 text-xs leading-5 text-gray-500">Contract Management owns signed agreements, renewals and expiry. Vendor compliance reads the linked record; uploading an agreement here alone does not verify it. A group agreement covering this entity must be selected explicitly.</p>{agreementResult && <div className="mt-3 flex items-start gap-2"><StatusBadge status={agreementResult.status} /><span className="text-xs leading-5 text-gray-600">{agreementResult.reason}</span></div>}<select className={`${fieldClass} mt-4`} value={vendor.agreementContractId || agreementResult?.sourceRecordId || ''} disabled={busy || !linkedContracts.length} onChange={event => chooseAgreement(event.target.value)}><option value="">{linkedContracts.length ? 'Select governing agreement' : 'No contract linked for this entity'}</option>{linkedContracts.map(contract => <option key={contract.id} value={contract.id}>{contract.contractNumber} · {contract.title} · {cleanLabel(contract.status)}{contract.vendorId !== vendor.id ? ' · shared' : ''}</option>)}</select><div className="mt-3 space-y-2">{linkedContracts.map(contract => <a key={contract.id} className="block rounded-lg bg-blue-50 px-3 py-2 text-xs font-bold text-blue-800 hover:bg-blue-100" href={`/contracts?view=register&record=${encodeURIComponent(contract.id)}`}>{contract.contractNumber} · {contract.title} →</a>)}</div>{!linkedContracts.length && <a className="mt-3 inline-block text-xs font-bold text-blue-700" href="/contracts?view=register">Open Contract Register to link an agreement →</a>}</section>}
        {detailTab === 'overview' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex justify-between gap-2"><div className="font-bold text-blue-950">Editable profile</div><button onClick={() => setEditingProfile(value => !value)} className="text-xs font-bold text-blue-700">{editingProfile ? 'Cancel' : 'Edit'}</button></div>{editingProfile ? <div className="mt-4 space-y-2">{(['legalName', 'registrationNumber', 'contactName', 'email', 'phone', 'address', 'services'] as const).map(key => <label key={key} className="block text-xs font-semibold text-gray-600">{cleanLabel(key)}<input className={`${fieldClass} mt-1`} value={profile[key]} onChange={event => setProfile({ ...profile, [key]: event.target.value })} /></label>)}<label className="block text-xs font-semibold text-gray-600">Category<select className={`${fieldClass} mt-1`} value={profile.categoryId} onChange={event => setProfile({ ...profile, categoryId: event.target.value })}>{configuration?.categories.map(category => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><div className="border-t pt-3 text-xs font-bold text-blue-950">e-Invoice supplier data</div>{(['tin', 'msic', 'businessActivity', 'sstNumber', 'tourismTaxNumber'] as const).map(key => <label key={key} className="block text-xs font-semibold text-gray-600">{cleanLabel(key)}<input className={`${fieldClass} mt-1`} value={profile.taxProfile[key]} onChange={event => setProfile({ ...profile, taxProfile: { ...profile.taxProfile, [key]: event.target.value } })} /></label>)}<button disabled={busy} onClick={saveProfile} className="rounded-lg bg-blue-800 px-4 py-2 text-xs font-bold text-white disabled:opacity-50">Save profile</button></div> : <p className="mt-2 text-xs text-gray-500">Identity, contact, tax data, service and category details can be corrected after intake. Changes require re-verification.</p>}</section>}
        {detailTab === 'overview' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><Building2 className="h-5 w-5" />Vendor profile</div><dl className="mt-4 space-y-3 text-sm"><div><dt className="text-gray-400">Contact</dt><dd className="font-medium">{vendor.contactName || 'Not recorded'}</dd></div><div><dt className="text-gray-400">Email</dt><dd className="font-medium">{vendor.email || 'Not recorded'}</dd></div><div><dt className="text-gray-400">Services</dt><dd className="font-medium">{vendor.services.join(', ') || 'Not recorded'}</dd></div><div><dt className="text-gray-400">Activities</dt><dd className="mt-1 flex flex-wrap gap-1">{vendor.activityTags.map(tag => <span key={tag} className="rounded bg-gray-100 px-2 py-1 text-xs">{cleanLabel(tag)}</span>)}</dd></div></dl></section>}
        {detailTab === 'overview' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="font-bold text-blue-950">e-Invoice supplier data</div><p className="mt-1 text-xs text-gray-500">Data extracted or entered for a Malaysian supplier record; this is not a live MyInvois validation.</p><dl className="mt-3 grid gap-3 text-sm sm:grid-cols-2">{([['TIN', vendor.taxProfile?.tin], ['MSIC', vendor.taxProfile?.msic], ['Business activity', vendor.taxProfile?.businessActivity], ['SST number (if applicable)', vendor.taxProfile?.sstNumber], ['Tourism tax number (if applicable)', vendor.taxProfile?.tourismTaxNumber]] as const).map(([label, value]) => <div key={label}><dt className="text-xs text-gray-400">{label}</dt><dd className="font-medium">{value || 'Not provided'}</dd></div>)}</dl></section>}

        {detailTab === 'people' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><Users className="h-5 w-5" />Personnel compliance</div><div className="mt-4 space-y-3">{vendor.personnel.map(person => { const results = vendor.requirementResults.filter(result => result.subjectId === person.id); return <div key={person.id} className="rounded-xl border border-gray-100 p-3"><div className="flex justify-between"><div><div className="text-sm font-bold">{person.name}</div><div className="text-xs text-gray-500">{cleanLabel(person.role)} · {person.identityMasked || 'ID not supplied'}</div></div><StatusBadge status={results.some(item => item.status === 'FAILED') ? 'FAILED' : results.every(item => item.status === 'PASSED') && results.length ? 'PASSED' : 'REVIEW_REQUIRED'} /></div><div className="mt-2 flex flex-wrap gap-2 text-[11px] font-bold"><span className={`rounded-full px-2 py-1 ${person.cidbCheckRequired ? 'bg-blue-50 text-blue-700' : 'bg-gray-100 text-gray-500'}`}>CIDB {person.cidbCheckRequired ? 'required' : 'not required'}</span><span className={`rounded-full px-2 py-1 ${person.doshCheckRequired ? 'bg-amber-50 text-amber-700' : 'bg-gray-100 text-gray-500'}`}>DOSH {person.doshCheckRequired ? 'required' : 'not required'}</span>{person.competencyScope && <span className="rounded-full bg-purple-50 px-2 py-1 text-purple-700">{person.competencyScope}</span>}</div><div className="mt-2 text-xs text-gray-500">{results.length} applicable requirement(s){person.siteAssignment ? ` · ${person.siteAssignment}` : ''}</div></div>})}{!vendor.personnel.length && <div className="text-sm text-gray-500">No personnel supplied.</div>}</div></section>}

        {detailTab === 'people' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><Link2 className="h-5 w-5" />Linked assets</div><div className="mt-4 space-y-2">{(vendor.entityLinks || []).map(link => <div key={link.id} className="rounded-lg bg-gray-50 p-3"><div className="text-sm font-bold">{link.entityName}</div><div className="text-xs text-gray-500">{cleanLabel(link.relationship)}{link.personnelName ? ` · ${link.personnelName}` : ''}</div></div>)}{!(vendor.entityLinks || []).length && <div className="text-sm text-gray-500">No assets linked.</div>}</div><div className="mt-4 space-y-2 border-t pt-4"><select className={fieldClass} value={assetId} onChange={event => setAssetId(event.target.value)}><option value="">Select Asset Management record</option>{assets.map(asset => <option key={asset.id} value={asset.id}>{asset.name} ({asset.registrationNumber})</option>)}</select><select className={fieldClass} value={relationship} onChange={event => { setRelationship(event.target.value); if (event.target.value !== 'OPERATOR') setOperatorId(''); }}><option value="OPERATOR">Operator</option><option value="MAINTENANCE_PROVIDER">Maintenance provider</option><option value="INSTALLER">Installer</option><option value="INSPECTOR">Inspector</option><option value="SUPPLIER">Supplier</option><option value="LICENCE_HOLDER">Licence holder</option></select>{relationship === 'OPERATOR' && <select className={fieldClass} value={operatorId} onChange={event => setOperatorId(event.target.value)}><option value="">Select qualified operator</option>{vendor.personnel.map(person => <option key={person.id} value={person.id}>{person.name} · {cleanLabel(person.role)}</option>)}</select>}<button onClick={addLink} disabled={!assetId || busy || (relationship === 'OPERATOR' && !operatorId)} className="w-full rounded-lg bg-blue-50 px-3 py-2 text-sm font-bold text-blue-800 disabled:opacity-50">Link asset</button></div></section>}

        {detailTab === 'checklist' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><Clock3 className="h-5 w-5" />Follow-up actions</div><div className="mt-4 space-y-3">{vendor.followUps.filter(item => item.status !== 'COMPLETED').slice(0, 8).map(item => <div key={item.id} className="rounded-xl border border-gray-100 p-3"><div className="text-sm font-bold">{item.title}</div><div className="mt-1 text-xs text-gray-500">Due {displayDate(item.dueDate)} · {item.owner}</div>{item.sourceUrl && <a href={item.sourceUrl} target="_blank" rel="noreferrer" className="mt-2 block text-xs font-bold text-blue-700">Open official source</a>}<button onClick={() => completeFollowUp(vendor.id, item.id)} className="mt-2 text-xs font-bold text-green-700">Mark completed</button></div>)}{!vendor.followUps.some(item => item.status !== 'COMPLETED') && <div className="text-sm text-gray-500">No open follow-ups.</div>}</div></section>}

        {detailTab === 'decisions' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><GitBranch className="h-5 w-5" />Approval workflow</div>{nextStage && !['APPROVED', 'CONDITIONALLY_APPROVED', 'REJECTED', 'SUSPENDED', 'BLACKLISTED'].includes(vendor.onboardingStatus) && <div className="mt-4"><div className="text-sm font-bold">Stage {vendor.currentApprovalStage + 1}: {nextStage.name}</div><div className="mt-1 text-xs text-gray-500">Required role: {nextStage.requiredRole} · Acting as Admin User</div><textarea className={`${fieldClass} mt-3`} rows={2} value={approvalNotes} onChange={event => setApprovalNotes(event.target.value)} placeholder="Decision notes" /><div className="mt-3 grid grid-cols-3 gap-2"><button onClick={() => decide('REJECTED')} disabled={busy} className="rounded-lg bg-red-50 px-2 py-2 text-xs font-bold text-red-700">Reject</button><button onClick={() => decide('CONDITIONAL')} disabled={busy} className="rounded-lg bg-amber-50 px-2 py-2 text-xs font-bold text-amber-700">Conditional</button><button onClick={() => decide('APPROVED')} disabled={busy || vendor.recommendation !== 'RECOMMEND_APPROVE'} className="rounded-lg bg-green-600 px-2 py-2 text-xs font-bold text-white disabled:opacity-40">Approve</button></div></div>}<div className="mt-4 space-y-2">{vendor.approvals.map(event => <div key={event.id} className="border-t pt-3 text-xs"><div className="font-bold">{event.stageName}: {event.decision}</div><div className="mt-1 text-gray-500">{event.actor} · {new Date(event.createdAt).toLocaleString()}</div></div>)}</div></section>}
        {detailTab === 'decisions' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="font-bold text-blue-950">Lifecycle controls</div><p className="mt-1 text-xs text-gray-500">Every suspension, blacklist or reinstatement is added to the audit trail.</p><textarea className={`${fieldClass} mt-3`} rows={2} value={lifecycleReason} onChange={event => setLifecycleReason(event.target.value)} placeholder="Required reason" /><div className="mt-3 grid grid-cols-2 gap-2">{['SUSPENDED', 'BLACKLISTED'].includes(vendor.onboardingStatus) ? <button onClick={() => changeLifecycle('APPROVED')} disabled={busy || vendor.recommendation !== 'RECOMMEND_APPROVE'} className="col-span-2 rounded-lg bg-green-50 px-3 py-2 text-xs font-bold text-green-700 disabled:opacity-40">Reinstate vendor</button> : <><button onClick={() => changeLifecycle('SUSPENDED')} disabled={busy} className="rounded-lg bg-amber-50 px-3 py-2 text-xs font-bold text-amber-700">Suspend</button><button onClick={() => changeLifecycle('BLACKLISTED')} disabled={busy} className="rounded-lg bg-red-50 px-3 py-2 text-xs font-bold text-red-700">Blacklist</button></>}</div></section>}
        {detailTab === 'performance' && <PerformanceForm vendor={vendor} />}
        {detailTab === 'decisions' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="font-bold text-blue-950">Audit trail</div><div className="mt-4 space-y-3">{vendor.auditTrail.slice(0, 10).map(event => <div key={event.id} className="border-l-2 border-blue-100 pl-3"><div className="text-xs font-bold">{cleanLabel(event.type)}</div><div className="mt-1 text-xs text-gray-500">{event.summary}</div><div className="mt-1 text-[10px] text-gray-400">{event.actor} · {new Date(event.createdAt).toLocaleString()}</div></div>)}</div></section>}
      </aside>
    </div>
  </div>;
}

export function Vendors() {
  const { vendors, dashboard, isLoading, refresh } = useVendors();
  const location = useLocation();
  useEffect(() => { void refresh(); }, [location.key]);
  const [params, setParams] = useSearchParams();
  const requested = params.get('view');
  const view: View = ['dashboard', 'register', 'followups', 'expiries', 'performance', 'rules'].includes(requested || '') ? requested as View : 'workflow';
  const setView = (next: View) => setParams(next === 'workflow' ? {} : { view: next });
  const [search, setSearch] = useState('');
  const [wizard, setWizard] = useState(false);
  const [bulk, setBulk] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [selectedDetailTab, setSelectedDetailTab] = useState<VendorDetailTab>('overview');
  useEffect(() => { setSelectedId(null); setSelectedDetailTab('overview'); }, [location.key]);
  const selected = vendors.find(vendor => vendor.id === selectedId);
  const filtered = vendors.filter(vendor => `${vendor.legalName} ${vendor.registrationNumber} ${vendor.categoryName}`.toLowerCase().includes(search.toLowerCase()));
  const openFollowUps = useMemo(() => vendors.flatMap(vendor => vendor.followUps.filter(item => item.status !== 'COMPLETED').map(item => ({ vendor, item }))), [vendors]);
  const followUpGroups = useMemo(() => vendors.map(vendor => {
    const items = vendor.followUps.filter(item => item.status !== 'COMPLETED');
    return { vendor, items, earliestDue: items.map(item => item.dueDate).sort()[0], owners: [...new Set(items.map(item => item.owner))] };
  }).filter(group => group.items.length).sort((a, b) => (a.earliestDue || '').localeCompare(b.earliestDue || '')), [vendors]);
  const expiries = useMemo(() => vendors.flatMap(vendor => vendor.documents.flatMap(document => { const expiry = document.extractedFields.find(field => field.key === 'expiryDate')?.value; return expiry ? [{ vendor, document, expiry }] : []; })).sort((a, b) => a.expiry.localeCompare(b.expiry)), [vendors]);

  if (selected) return <div className="mx-auto max-w-7xl p-4 sm:p-6 lg:p-8"><VendorDetail vendor={selected} initialTab={selectedDetailTab} onBack={() => { setSelectedId(null); setSelectedDetailTab('overview'); }} /></div>;
  return <div className="mx-auto max-w-7xl space-y-6 p-4 sm:p-6 lg:p-8">
    <div className="flex flex-wrap items-start justify-between gap-4"><div><h1 className="text-2xl font-bold text-blue-950">{view === 'workflow' ? 'Vendor onboarding workflow' : ({ dashboard: 'Vendor Overview', register: 'Vendor Register', followups: 'Vendor Follow-ups', expiries: 'Vendor Expiries', performance: 'Vendor Performance', rules: 'Vendor Rules' } as Record<Exclude<View, 'workflow'>, string>)[view]}</h1><p className="mt-1 text-sm text-gray-500">Use the sidebar for registers and configuration; this page focuses on the selected review work.</p></div><div className="flex flex-wrap gap-2"><button onClick={() => setBulk(true)} className="inline-flex items-center gap-2 rounded-lg border border-gray-200 bg-white px-4 py-2.5 text-sm font-bold text-gray-700"><Upload className="h-4 w-4" />Bulk import</button><button onClick={() => setWizard(true)} className="inline-flex items-center gap-2 rounded-lg bg-blue-800 px-4 py-2.5 text-sm font-bold text-white"><Plus className="h-4 w-4" />Start onboarding</button></div></div>

    {isLoading ? <div className="flex min-h-80 items-center justify-center text-gray-500"><Loader2 className="mr-2 h-5 w-5 animate-spin" />Loading vendor management…</div> : <>
      {view === 'workflow' && <div className="grid gap-5 lg:grid-cols-3">{([
        { title: '1. Collect vendor evidence', description: 'Invite or register a vendor, then upload documents for AI classification and prefill.', action: 'Start onboarding', onClick: () => setWizard(true), icon: Upload },
        { title: '2. Resolve review actions', description: `${openFollowUps.length} open follow-up(s) need verification, missing documents or a human decision.`, action: 'Open follow-ups', onClick: () => setView('followups'), icon: ClipboardCheck },
        { title: '3. Monitor validity', description: `${expiries.length} dated document(s) tracked across vendors and personnel. Review upcoming expiries and annual performance.`, action: 'Review expiries', onClick: () => setView('expiries'), icon: Bell },
      ] as const).map(item => <section key={item.title} className="flex flex-col rounded-2xl border border-gray-200 bg-white p-6 shadow-sm"><item.icon className="h-7 w-7 text-blue-700" /><h2 className="mt-5 text-lg font-bold text-blue-950">{item.title}</h2><p className="mt-2 flex-1 text-sm leading-6 text-gray-600">{item.description}</p><button onClick={item.onClick} className="mt-6 rounded-xl bg-blue-50 px-4 py-2.5 text-left text-sm font-bold text-blue-800 hover:bg-blue-100">{item.action} →</button></section>)}</div>}
      {view === 'dashboard' && <div className="space-y-6">{!vendors.length ? <div className="overflow-hidden rounded-2xl bg-gradient-to-br from-blue-950 via-blue-900 to-indigo-900 p-8 text-white shadow-sm lg:p-10"><div className="text-xs font-bold uppercase tracking-[0.2em] text-yellow-400">Vendor compliance workspace</div><h2 className="mt-3 max-w-2xl text-3xl font-bold">Turn unstructured vendor evidence into a controlled onboarding decision.</h2><p className="mt-4 max-w-2xl text-sm leading-6 text-blue-100">Start with a vendor profile or bulk master file. The system determines CIDB, DOSH, OSHA and commercial requirements from the declared work and personnel roles.</p><button onClick={() => setWizard(true)} className="mt-7 inline-flex items-center gap-2 rounded-lg bg-yellow-400 px-5 py-3 text-sm font-bold text-blue-950"><Plus className="h-5 w-5" />Onboard first vendor</button></div> : <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{([
        ['Total vendors', dashboard?.totalVendors || 0, Building2, 'bg-blue-50 text-blue-700'], ['In onboarding', dashboard?.onboarding || 0, Clock3, 'bg-indigo-50 text-indigo-700'], ['Review required', dashboard?.reviewRequired || 0, ShieldAlert, 'bg-purple-50 text-purple-700'], ['Non-compliant', dashboard?.nonCompliant || 0, AlertTriangle, 'bg-red-50 text-red-700'], ['High-risk cases', dashboard?.highRisk || 0, ShieldAlert, 'bg-red-50 text-red-700'],
      ] as Array<[string, number, LucideIcon, string]>).map(([label, value, Icon, color]) => <div key={label} className="flex items-center justify-between rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div><div className="text-sm text-gray-500">{label}</div><div className="mt-1 text-3xl font-bold">{value}</div></div><div className={`rounded-xl p-3 ${color}`}><Icon className="h-5 w-5" /></div></div>)}</div><div className="grid gap-6 lg:grid-cols-[1.3fr_0.7fr]"><section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><div className="font-bold text-blue-950">Recent vendors</div><button onClick={() => setView('register')} className="text-sm font-bold text-blue-700">View register</button></div><div className="mt-4 divide-y">{vendors.slice(0, 6).map(vendor => <button key={vendor.id} onClick={() => setSelectedId(vendor.id)} className="flex w-full items-center justify-between gap-3 py-4 text-left"><div><div className="font-bold">{vendor.legalName}</div><div className="mt-1 text-xs text-gray-500">{vendor.categoryName} · {vendor.registrationNumber}</div></div><div className="flex items-center gap-2"><StatusBadge status={vendor.onboardingStatus} /><ChevronRight className="h-4 w-4 text-gray-300" /></div></button>)}</div></section><section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><Bell className="h-5 w-5" />Expiry notifications</div><div className="mt-4 space-y-3">{dashboard?.notifications.slice(0, 6).map(item => <div key={item.id} className="rounded-lg bg-gray-50 p-3"><div className="text-sm font-bold">{item.vendorName}</div><div className="mt-1 text-xs text-gray-600">{item.title}: {item.message}</div></div>)}{!dashboard?.notifications.length && <div className="text-sm text-gray-500">No expiry alerts today.</div>}</div><div className="mt-5 flex items-center justify-between border-t pt-4 text-sm"><span className="text-gray-500">Demo email outbox</span><span className="font-bold text-blue-800">{dashboard?.outbox.length || 0}</span></div></section></div></>}</div>}

      {view === 'register' && <section className="rounded-xl border border-gray-100 bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-3 border-b p-5"><div><h2 className="font-bold text-blue-950">Vendor Register</h2><p className="mt-1 text-sm text-gray-500">{vendors.length} vendor record(s)</p></div><div className="relative"><Search className="absolute left-3 top-2.5 h-4 w-4 text-gray-400" /><input className="rounded-lg border border-gray-200 py-2 pl-9 pr-3 text-sm" value={search} onChange={event => setSearch(event.target.value)} placeholder="Search vendors" /></div></div><div className="overflow-x-auto"><table className="w-full min-w-[840px] text-left text-sm"><thead className="bg-gray-50 text-xs uppercase text-gray-500"><tr><th className="px-5 py-3">Vendor</th><th className="px-5 py-3">Category</th><th className="px-5 py-3">Status</th><th className="px-5 py-3">Recommendation</th><th className="px-5 py-3">Personnel</th><th className="px-5 py-3">Open actions</th><th className="px-5 py-3"></th></tr></thead><tbody className="divide-y">{filtered.map(vendor => <tr key={vendor.id}><td className="px-5 py-4"><div className="font-bold">{vendor.legalName}</div><div className="text-xs text-gray-500">{vendor.registrationNumber}</div></td><td className="px-5 py-4">{vendor.categoryName}</td><td className="px-5 py-4"><StatusBadge status={vendor.onboardingStatus} /></td><td className="px-5 py-4 text-xs font-medium">{cleanLabel(vendor.recommendation)}</td><td className="px-5 py-4">{vendor.personnel.length}</td><td className="px-5 py-4">{vendor.followUps.filter(item => item.status !== 'COMPLETED').length}</td><td className="px-5 py-4"><button onClick={() => setSelectedId(vendor.id)} className="font-bold text-blue-700">Open</button></td></tr>)}</tbody></table></div></section>}

      {view === 'followups' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><Clock3 className="h-5 w-5" />Vendor cases requiring follow-up</div><p className="mt-1 text-sm text-gray-500">One review card per vendor. Open the case to work through its checklist, request missing evidence and complete verified items.</p><div className="mt-4 grid gap-4 lg:grid-cols-2">{followUpGroups.map(({ vendor, items, earliestDue, owners }) => <article key={vendor.id} className="rounded-xl border border-gray-100 p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="font-bold text-blue-950">{vendor.legalName}</div><div className="mt-1 text-xs text-gray-500">{vendor.categoryName} · {items.length} open action{items.length === 1 ? '' : 's'}</div></div><StatusBadge status={vendor.onboardingStatus} /></div><div className="mt-4 grid grid-cols-2 gap-3 rounded-lg bg-gray-50 p-3 text-xs"><div><div className="text-gray-400">Next due</div><div className="mt-1 font-bold">{displayDate(earliestDue)}</div></div><div><div className="text-gray-400">Responsible teams</div><div className="mt-1 font-bold">{owners.slice(0, 2).join(', ')}{owners.length > 2 ? ` +${owners.length - 2}` : ''}</div></div></div><details className="mt-3 text-xs text-gray-600"><summary className="cursor-pointer font-bold text-blue-700">Preview requested items</summary><ul className="mt-2 space-y-1 pl-4">{items.slice(0, 5).map(item => <li key={item.id} className="list-disc">{item.title}</li>)}{items.length > 5 && <li className="list-disc">And {items.length - 5} more</li>}</ul></details><button onClick={() => { setSelectedDetailTab('checklist'); setSelectedId(vendor.id); }} className="mt-4 w-full rounded-lg bg-blue-800 px-4 py-2.5 text-sm font-bold text-white">Review vendor checklist</button></article>)}{!followUpGroups.length && <div className="py-10 text-center text-gray-500 lg:col-span-2">No vendor cases need follow-up.</div>}</div></section>}

      {view === 'expiries' && <section className="rounded-xl border border-gray-100 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 font-bold text-blue-950"><Bell className="h-5 w-5" />Document and licence expiries</div><div className="mt-4 overflow-x-auto"><table className="w-full min-w-[700px] text-left text-sm"><thead className="border-b text-xs uppercase text-gray-500"><tr><th className="px-4 py-3">Vendor</th><th className="px-4 py-3">Evidence</th><th className="px-4 py-3">Subject</th><th className="px-4 py-3">Expiry</th></tr></thead><tbody className="divide-y">{expiries.map(item => <tr key={item.document.id}><td className="px-4 py-4"><button onClick={() => setSelectedId(item.vendor.id)} className="font-bold text-blue-800">{item.vendor.legalName}</button></td><td className="px-4 py-4">{cleanLabel(item.document.documentType)}</td><td className="px-4 py-4">{item.document.subjectName || 'Company'}</td><td className="px-4 py-4 font-bold">{displayDate(item.expiry)}</td></tr>)}</tbody></table>{!expiries.length && <div className="py-10 text-center text-gray-500">No extracted expiry dates yet.</div>}</div></section>}

      {view === 'performance' && <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{vendors.map(vendor => <button key={vendor.id} onClick={() => setSelectedId(vendor.id)} className="rounded-xl border border-gray-100 bg-white p-5 text-left shadow-sm"><div className="flex justify-between"><div className="font-bold">{vendor.legalName}</div><Gauge className="h-5 w-5 text-blue-700" /></div>{vendor.performanceAssessments[0] ? <><div className="mt-4 text-3xl font-bold text-blue-800">{vendor.performanceAssessments[0].weightedScore}</div><div className="mt-1 text-xs text-gray-500">Next review {displayDate(vendor.performanceAssessments[0].nextReviewDate)}</div></> : <div className="mt-4 text-sm text-amber-700">Annual performance review required</div>}</button>)}</div>}
      {view === 'rules' && <VendorRuleBuilder />}
    </>}

    <VendorOnboardingWizard open={wizard} onClose={() => setWizard(false)} onCreated={vendor => setSelectedId(vendor.id)} />
    <BulkVendorImportModal open={bulk} onClose={() => setBulk(false)} />
  </div>;
}
